TOOL_BY_ID = {tool["tool_id"]: tool for tool in TOOL_CATALOG}
TOOL_BY_NAME = {tool["canonical_name"]: tool for tool in TOOL_CATALOG}


def validate_tool_catalog() -> list[str]:
    """Return invariant violations; an empty list means metadata is structurally complete."""
    errors: list[str] = []
    ids = [tool.get("tool_id", "") for tool in TOOL_CATALOG]
    names = [tool.get("canonical_name", "") for tool in TOOL_CATALOG]
    if len(TOOL_CATALOG) != 100:
        errors.append(f"Expected exactly 100 tools, found {len(TOOL_CATALOG)}.")
    if len(ids) != len(set(ids)):
        errors.append("Tool IDs are not unique.")
    if set(ids) != {f"T{i:03d}" for i in range(1, 101)}:
        errors.append("Tool IDs must be exactly T001 through T100.")
    if len(names) != len(set(names)):
        errors.append("Canonical tool names are not unique.")
    for tool in TOOL_CATALOG:
        if tool.get("target_minimum_tier") not in VALID_TOOL_TIERS:
            errors.append(f"{tool.get('tool_id')}: invalid tier {tool.get('target_minimum_tier')!r}.")
        if tool.get("implementation_status") not in VALID_IMPLEMENTATION_STATUSES:
            errors.append(f"{tool.get('tool_id')}: invalid implementation status.")
        missing = [field for field in ["tool_id","canonical_name","workbench","target_minimum_tier","existing_module_or_route","source_files","implementation_status","calculation_or_action","input_contract","output_contract","persistence_scope","external_dependency","entitlement_enforcement_points","unit_test","integration_test","browser_test","evidence_link_or_artifact","remaining_gap","owner_or_next_action"] if not str(tool.get(field, "")).strip()]
        if missing:
            errors.append(f"{tool.get('tool_id')}: missing fields {missing}.")
    return errors
